draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw observer
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 20, H/2 + 40);
  ctx.stroke();

  // draw model
  ctx.beginPath();
  ctx.arc(3*W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 + 20);
  ctx.lineTo(3*W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 + 30);
  ctx.lineTo(3*W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 + 30);
  ctx.lineTo(3*W/4 + 20, H/2 + 40);
  ctx.stroke();

  // draw bandura (guitar-like instrument)
  ctx.fillStyle = 'brown';
  ctx.fillRect(3*W/4 - 30, H/2 + 50, 60, 10);
  ctx.fillStyle = 'black';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(3*W/4 - 20, H/2 + 60);
  ctx.lineTo(3*W/4 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4 + 20, H/2 + 60);
  ctx.lineTo(3*W/4 + 20, H/2 + 70);
  ctx.stroke();

  // draw observer watching
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 20 + 20 * Math.sin(t));
  ctx.stroke();

  // draw observer learning
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 50 + 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
